INSERT INTO public.invitations (name, invitation_text) VALUES ('李文静', '静女其姝，俟我于城隅。大咖生辰，诚邀袍姝线上赴宴！<p class="sign">—— 陈山石 谨邀</p>') ON CONFLICT (name) DO NOTHING;
INSERT INTO public.invitations (name, invitation_text) VALUES ('张翀赫', '一飞翀昊苍，齐红日煊赫。特邀翀赫学长线上赴宴！<p class="sign">—— 陈山石 谨邀</p>') ON CONFLICT (name) DO NOTHING;
INSERT INTO public.invitations (name, invitation_text) VALUES ('张颖', '草木嫩发，穗颖春三月。诚邀张颖同学线上赴宴！<p class="sign">—— 陈山石 谨邀</p>') ON CONFLICT (name) DO NOTHING;
INSERT INTO public.invitations (name, invitation_text) VALUES ('陈彦彤', '金光闪闪，1695的彤彤大人，小的邀请您前往线上赴宴！<p class="sign">—— 陈山石 谨邀</p>') ON CONFLICT (name) DO NOTHING;
INSERT INTO public.invitations (name, invitation_text) VALUES ('楚嫣涵', '笑语嫣然，楚硕有内涵。小弟满怀赤诚地邀请您线上赴宴！<p class="sign">—— 陈山石 谨邀</p>') ON CONFLICT (name) DO NOTHING;
INSERT INTO public.invitations (name, invitation_text) VALUES ('代鹏', '九万里风，无己无功无名，特邀鸟哥大圣前来线上赴宴！<p class="sign">—— 陈山石 谨邀</p>') ON CONFLICT (name) DO NOTHING;
INSERT INTO public.invitations (name, invitation_text) VALUES ('邓宇恬', '宇宙渺远无际，幸好我能碰到你。羽天和珂霖是一辈子的好朋友！<p class="sign">—— 陈山石 谨邀</p>') ON CONFLICT (name) DO NOTHING;
INSERT INTO public.invitations (name, invitation_text) VALUES ('董秋书', '秋夜微凉，我致书与你：诚邀董秋书同学参加我的线上宴会！<p class="sign">—— 陈山石 谨邀</p>') ON CONFLICT (name) DO NOTHING;
INSERT INTO public.invitations (name, invitation_text) VALUES ('杜唐雨', '小雨如酥润，唐雨似仙神，无敌努力的豆哥请来线上赴宴吧！<p class="sign">—— 陈山石 谨邀</p>') ON CONFLICT (name) DO NOTHING;
